# Let me try a different approach: maybe the problem is that I need
# to identify multiple enclosed regions, and my algorithm only finds connected
# components of background color.

# Let me re-examine the demo to see if there are multiple enclosed 5-regions
# that my algorithm should handle correctly.

demo_input = [
    [5, 5, 5, 9, 5, 5, 5, 5, 5, 5, 5, 9, 5, 5, 5],
    [5, 5, 5, 9, 5, 5, 5, 5, 5, 5, 5, 9, 5, 5, 5],
    [9, 9, 9, 9, 9, 9, 9, 5, 5, 5, 5, 9, 5, 5, 5],
    [9, 5, 5, 5, 5, 5, 9, 5, 5, 5, 9, 9, 9, 9, 9],
    [9, 5, 5, 5, 5, 5, 9, 9, 9, 9, 9, 5, 5, 5, 9],
    [9, 5, 5, 5, 5, 5, 9, 5, 5, 5, 9, 9, 9, 9, 9],
    [9, 5, 5, 5, 5, 5, 9, 5, 5, 5, 5, 5, 5, 5, 5],
    [9, 9, 9, 9, 9, 9, 9, 5, 5, 5, 5, 5, 5, 5, 5],
]

rows, cols = 8, 15

# Find all reachable 5s from the edge
from collections import deque

def can_reach_edge(grid, val, start_r, start_c, rows, cols):
    visited = [[False]*cols for _ in range(rows)]
    queue = deque([(start_r, start_c)])
    visited[start_r][start_c] = True

    while queue:
        r, c = queue.popleft()

        if r == 0 or r == rows-1 or c == 0 or c == cols-1:
            return True

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == val and not visited[nr][nc]:
                    visited[nr][nc] = True
                    queue.append((nr, nc))
    return False

# Check each 5 to see if it can reach the edge
unreachable_cells = []
for r in range(rows):
    for c in range(cols):
        if demo_input[r][c] == 5:
            if not can_reach_edge(demo_input, 5, r, c, rows, cols):
                unreachable_cells.append((r, c))

# Fill all 5s and check the output
demo_output = [row[:] for row in demo_input]
for r in range(rows):
    for c in range(cols):
        if demo_input[r][c] == 5:
            if not can_reach_edge(demo_input, 5, r, c, rows, cols):
                demo_output[r][c] = 4  # fill with 4

print("Input cells that become 4:")
print(sorted(unreachable_cells))

print("\nInput:")
for row in demo_input:
    print(" ".join(str(x) for x in row))

print("\nOutput:")
for row in demo_output:
    print(" ".join(str(x) for x in row))

